import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        System.out.println(compute(n, m));
    }

    static int[] extendedEuclidean(int a, int b) {
        int r_prev = a, r_curr = b;
        int s_prev = 1, s_curr = 0;
        int t_prev = 0, t_curr = 1;
        while (r_curr != 0) {
            int q = r_prev / r_curr;
            int r_temp = r_prev - q * r_curr;
            r_prev = r_curr;
            r_curr = r_temp;

            int s_temp = s_prev - q * s_curr;
            s_prev = s_curr;
            s_curr = s_temp;

            int t_temp = t_prev - q * t_curr;
            t_prev = t_curr;
            t_curr = t_temp;
        }
        return new int[]{r_prev, s_prev};
    }

    static int[] binomialCoeffs(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int)(((long)C[k + 1] * (k + 1)) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }

    static int compute(int n, int M) {
        List<List<int[]>> K = new ArrayList<>();
        List<int[]> firstLayer = new ArrayList<>();
        firstLayer.add(new int[]{1});
        K.add(firstLayer);
        for (int i = 0; i < n - 1; i++) {
            List<int[]> prevLayer = K.get(i);
            int size_prev = prevLayer.size();
            List<int[]> newLayer = new ArrayList<>();
            for (int j = 0; j < size_prev + i + 1; j++) {
                int[] row = new int[i + 2];
                Arrays.fill(row, 0);
                newLayer.add(row);
            }
            K.add(newLayer);
            for (int j = 0; j < size_prev; j++) {
                int[] rowPrev = prevLayer.get(j);
                int lenRowPrev = rowPrev.length;
                for (int k = 0; k < lenRowPrev; k++) {
                    int val = rowPrev[k];
                    for (int h = 0; h < i + 1; h++) {
                        K.get(i + 1).get(j + h)[k] = (int)(((long)K.get(i + 1).get(j + h)[k] + val) % M);
                    }
                    K.get(i + 1).get(j + i + 1)[i + 1] = (int)(((long)K.get(i + 1).get(j + i + 1)[i + 1] + val) % M);
                }
            }
        }
        int[] C = binomialCoeffs(n, M);
        long totalSum = 0;
        for (int i = 1; i < n; i++) {
            List<int[]> layer = K.get(i);
            int ni = layer.size();
            int mi = layer.get(0).length;
            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(layer.get(j), 0, S[j], 0, mi);
            }
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (int)(((long)S[j][k] + S[j][k + 1]) % M);
                }
            }
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (int)(((long)S[j][k] + S[j - 1][k]) % M);
                }
            }
            long sum_value = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    long product = ((long)layer.get(j)[k] * S[j - 1][k + 1]) % M;
                    sum_value = (sum_value + product) % M;
                }
            }
            int c = C[i + 1];
            sum_value = (sum_value * c) % M;
            totalSum = (totalSum + sum_value) % M;
        }
        return (int) totalSum;
    }
}
